use hawdb_core::{Catalog, Value};
use hawdb_storage::{config::{DurabilityPolicy, StorageResidencyMode, WalReplayConfig}, store::GraphStore, NodeId};
use std::{collections::{BTreeMap,BTreeSet},path::PathBuf,time::Instant};
fn main() {
 let args: Vec<_> = std::env::args().collect();
 let path=PathBuf::from(&args[1]);
 let position: usize=args[2].parse().unwrap();
 let width: usize=args[3].parse().unwrap();
 let calls: usize=args[4].parse().unwrap();
 let config=WalReplayConfig { residency_mode: StorageResidencyMode::OutOfCore, ..WalReplayConfig::default() };
 let identity=path.with_extension("ids.json");
 if !identity.exists() {
  let mut catalog=Catalog::default();
  let mut store=GraphStore::open_with_durability_and_replay_config(&path,&mut catalog,DurabilityPolicy::default(),config).unwrap();
  let mut ids=Vec::new();
  for row in 0..256 {
   let properties=(0..16).map(|column| (format!("property-{column:04}"),Value::Int((row*16+column) as i64))).collect::<BTreeMap<_,_>>();
   ids.push(store.create_node(&mut catalog,"Item",properties).unwrap().0);
  }
  store.checkpoint(&catalog).unwrap();
  std::fs::write(&identity,serde_json::to_vec(&ids).unwrap()).unwrap();
 }
 let ids: Vec<u64>=serde_json::from_slice(&std::fs::read(&identity).unwrap()).unwrap();
 let mut catalog=Catalog::default();
 let store=GraphStore::open_with_durability_and_replay_config(&path,&mut catalog,DurabilityPolicy::default(),config).unwrap();
 let residency=store.storage_residency_report();
 assert!(residency.out_of_core);
 assert_eq!(residency.delta_node_count,0);
 assert_eq!(residency.canonical_node_count,256);
 let columns=(0..width).map(|i|format!("property-{i:04}")).collect::<BTreeSet<_>>();
 let mut count=0usize;
 let mut admitted_bytes=0usize;
 let mut admit=|bytes| { count+=1;admitted_bytes+=bytes;Ok(()) };
 for _ in 0..10 {store.projected_node_owned_admitted(NodeId(ids[position]),&columns,&mut admit).unwrap().unwrap();}
 let before=store.storage_residency_report();
 let mut elapsed=0;
 for _ in 0..calls {
  let started=Instant::now();
  let row=store.projected_node_owned_admitted(NodeId(ids[position]),&columns,&mut admit).unwrap().unwrap();
  elapsed+=started.elapsed().as_nanos();
  assert_eq!(row.id,NodeId(ids[position]));
  assert_eq!(row.properties.len(),width);
  for column in 0..width {assert_eq!(row.properties[&format!("property-{column:04}")],Value::Int((position*16+column) as i64));}
 }
 let after=store.storage_residency_report();
 assert_eq!(count,calls+10);
 println!("{}",serde_json::json!({"position":position,"width":width,"calls":calls,"point_ns":elapsed,"admitted_bytes":admitted_bytes,"admission_calls":count,"canonical_generation":residency.canonical_generation,"canonical_node_count":residency.canonical_node_count,"delta_node_count":residency.delta_node_count,"cache_hits":after.segment_cache_hit_count-before.segment_cache_hit_count,"cache_misses":after.segment_cache_miss_count-before.segment_cache_miss_count,"cache_pinned_before":before.segment_cache_pinned_bytes,"cache_pinned_after":after.segment_cache_pinned_bytes,"scope":"checkpointed/reopened canonical projected node-by-id read, warmed cache, admission+decode timing; excludes query optimizer, index seek, consumer/drop, cold latency and full-query performance acceptance"}));
}
